(function(){'use strict';const C=window.MT_CUSTOM_CALCULATORS,$=id=>document.getElementById(id),KEY='mt.custom-calculators.v1',esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let definitions=[],opened=null,pending=null,writable=true,last=null;
let nb=false;try{nb=JSON.parse(localStorage.getItem('mt.locale.v1'))==='nb';}catch{}const tr=(en,no)=>nb?no:en;
const templates=[
 {title:'Box volume',name:['Box volume','Volum av kasse'],output:['Volume','Volum'],unit:'m³',expression:'length*width*height',variables:[['length','Length','Lengde','m',3],['width','Width','Bredde','m',2],['height','Height','Høyde','m',1.5]]},
 {title:'Hydraulic input power',name:['Hydraulic input power','Hydraulisk tilført effekt'],output:['Input power','Tilført effekt'],unit:'kW',expression:'pressure*flow/(600*efficiency)',variables:[['pressure','Pressure difference','Trykkforskjell','bar',150],['flow','Volume flow','Volumstrøm','L/min',30],['efficiency','Efficiency fraction','Virkningsgrad som andel','',.85]]},
 {title:'Tank liquid mass',name:['Tank liquid mass','Væskemasse i tank'],output:['Liquid mass','Væskemasse'],unit:'t',expression:'volume*density/1000',variables:[['volume','Volume','Volum','m³',100],['density','Density','Tetthet','kg/m³',850]]},
 {title:'Three-phase active power',name:['Three-phase active power','Trefaset aktiv effekt'],output:['Active power','Aktiv effekt'],unit:'kW',expression:'sqrt(3)*voltage*current*pf/1000',variables:[['voltage','Line voltage','Linjespenning','V',440],['current','Line current','Linjestrøm','A',100],['pf','Power factor','Effektfaktor','',.8]]}
];
function status(text){$('custom-status').textContent=text;}
try{const raw=localStorage.getItem(KEY);if(raw)definitions=C.parseFile(raw);}catch{writable=false;status('Saved calculator data could not be read. Export your current definition; existing storage has not been overwritten.');}
function options(){const before=$('saved-calculators').value;$('saved-calculators').innerHTML='<option value="">Choose a saved calculator</option>'+definitions.map((d,i)=>'<option value="'+i+'" data-user-content>'+esc(d.name)+'</option>').join('');$('saved-calculators').value=before;}
function persist(next){if(!writable){status('Saved calculator data could not be read. Export your current definition; existing storage has not been overwritten.');return false;}try{const bytes=JSON.stringify({version:1,calculators:next});if(bytes.length>200000||next.length>50)throw Error();localStorage.setItem(KEY,bytes);definitions=next;options();return true;}catch{status('The browser could not save this definition. Export it as JSON to keep a copy.');return false;}}
function row(v){const el=document.createElement('div');el.className='variable-row';el.innerHTML='<label>Variable identifier<input data-key="name" maxlength="24" data-user-content value="'+esc(v.name)+'" spellcheck="false"></label><label>Input label<input data-key="label" maxlength="80" data-user-content value="'+esc(v.label)+'"></label><label>Unit label<input data-key="unit" maxlength="24" data-user-content value="'+esc(v.unit)+'"></label><label>Input value<input data-key="value" type="text" inputmode="decimal" data-user-content value="'+esc(v.value)+'"></label><button type="button" data-remove>Remove variable</button>';$('variables').append(el);return el;}
function read(){return C.definition({name:$('calculator-name').value,expression:$('calculator-expression').value,output:$('calculator-output').value,unit:$('calculator-unit').value,variables:[...$('variables').children].map(el=>Object.fromEntries([...el.querySelectorAll('input')].map(n=>[n.dataset.key,n.value])))});}
function update(){try{last=C.calculate(read());$('custom-error').hidden=true;$('custom-result').textContent=last.definition.output+': '+new Intl.NumberFormat(window.MT_I18N?.numberLocale|| (nb?'nb-NO':'en-GB'),{maximumSignificantDigits:10}).format(last.value)+(last.definition.unit?' '+last.definition.unit:'');$('custom-substitution').textContent=last.substitution+' = '+last.value;$('export-calculator').disabled=false;$('save-calculator').disabled=false;$('replace-calculator').disabled=opened===null;}catch(e){last=null;$('custom-result').textContent='';$('custom-substitution').textContent='';$('custom-error').textContent=e.message;$('custom-error').hidden=false;$('export-calculator').disabled=true;$('save-calculator').disabled=true;$('replace-calculator').disabled=true;}}
function load(d,index=null){opened=index;$('calculator-name').value=d.name;$('calculator-expression').value=d.expression;$('calculator-output').value=d.output;$('calculator-unit').value=d.unit;$('variables').replaceChildren();d.variables.forEach(row);update();}
function template(t){return {name:t.name[nb?1:0],output:t.output[nb?1:0],unit:t.unit,expression:t.expression,variables:t.variables.map(([name,en,no,unit,value])=>({name,label:nb?no:en,unit,value}))};}
for(const t of templates){const b=document.createElement('button');b.type='button';b.textContent=t.title;b.onclick=()=>{load(template(t));status('Template loaded. Edit the formula and input values.');};$('templates').append(b);}
$('calculator-editor').addEventListener('submit',e=>{e.preventDefault();update();});$('calculator-editor').addEventListener('input',update);
$('variables').addEventListener('click',e=>{if(!e.target.closest('[data-remove]'))return;e.target.closest('.variable-row').remove();update();});
$('add-variable').onclick=()=>{if($('variables').children.length>=12){status('A calculator supports at most 12 variables.');return;}let n=1;const taken=[...$('variables').querySelectorAll('[data-key=name]')].map(x=>x.value);while(taken.includes('x'+n))n++;row({name:'x'+n,label:tr('Input','Inndata')+' '+n,unit:'',value:1}).querySelector('input').focus();update();};
$('open-calculator').onclick=()=>{const v=$('saved-calculators').value;if(v!==''&&definitions[Number(v)]){load(definitions[Number(v)],Number(v));status('Saved calculator opened.');}};
$('delete-calculator').onclick=()=>{const v=$('saved-calculators').value;if(v==='')return;const i=Number(v);if(!definitions[i])return;if(persist(definitions.filter((_,n)=>n!==i))){if(opened===i)opened=null;else if(opened>i)opened--;update();status('Selected definition deleted.');}};
$('save-calculator').onclick=()=>{try{const d=read();if(persist([...definitions,d])){opened=definitions.length-1;$('saved-calculators').value=String(opened);update();status('Calculator definition saved in this browser.');}}catch(e){status(e.message);}};
$('replace-calculator').onclick=()=>{try{if(opened===null||!definitions[opened])return;const next=definitions.slice();next[opened]=read();if(persist(next))status('Opened calculator updated.');}catch(e){status(e.message);}};
$('export-calculator').onclick=()=>{try{const d=read(),url=URL.createObjectURL(new Blob([JSON.stringify({version:1,calculators:[d]},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='MarineTools-calculator.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('Calculator definition exported.');}catch(e){status(e.message);}};
$('import-calculators').onchange=async e=>{pending=null;$('confirm-import').hidden=true;$('import-review').replaceChildren();try{const file=e.target.files?.[0];if(!file)return;if(file.size>200000)throw Error('The calculator file is too large.');pending=C.parseFile(await file.text());if(!pending.length)throw Error('The file contains no calculator definitions.');if(pending.length+definitions.length>50)throw Error('A browser library supports at most 50 calculator definitions.');for(const d of pending){const p=document.createElement('p');p.dataset.userContent='';p.textContent=d.name+' · '+d.expression+' → '+d.output+(d.unit?' ('+d.unit+')':'');$('import-review').append(p);}$('confirm-import').hidden=false;$('import-status').textContent='Review the definitions above, then add them if they are the ones you want.';}catch(err){pending=null;$('import-review').replaceChildren();$('import-status').textContent=err.message;}finally{e.target.value='';}};
$('confirm-import').onclick=()=>{if(pending&&persist([...definitions,...pending])){pending=null;$('confirm-import').hidden=true;$('import-review').replaceChildren();$('import-status').textContent='Reviewed definitions added to this browser.';}};
window.addEventListener('mt-locale-change',()=>{nb=window.MT_I18N.locale==='nb';update();});options();load(template(templates[0]));window.MT_CUSTOM_UI={read,update,get definitions(){return definitions.slice();}};
})();
